void Record(NodeRunStatus s,IReadOnlyDictionary<string,PortValue>? outputs=null,string? code=null,string? message=null,uint? nativeCode=null){records[id]=new(id,s,outputs??Empty(),sw.Elapsed.TotalMilliseconds,code,message){NativeErrorCode=nativeCode};workflow.Update(id);Report(id,s,message);}
if(!n.Enabled){Record(NodeRunStatus.Skipped,message:"Disabled");continue;}if(cancellationToken.IsCancellationRequested){Record(NodeRunStatus.Cancelled,code:"Cancelled");continue;}
if(executionEdges.Where(e=>e.ToNode==id).Any(e=>suppressed.Contains(e.FromNode)||(selectedSuccessors.TryGetValue(e.FromNode,out var selected)&&!selected.Contains(id))||records[e.FromNode].Status is not(NodeRunStatus.Success or NodeRunStatus.NoMatch))){Record(NodeRunStatus.Skipped,code:"ExecutionPredecessorUnavailable");continue;}

 WorkflowCallbacks.PublishModuleResult(
  () => {
